// Slices of the motion records of three real Insta360 videos, for the tests of insta360_motion.dart: an X3 of the
// owner of the app (firmware v1.0.93), the public X4 (v0.4.7) and X5 (v1.0.2) samples of the RAW 360 lots. For each:
// the metadata fields the reader uses (model, firmware, fields 24, 25, 62 and 65; no serial number), the raw IMU
// samples from 20 ms before the first frame to 180 ms after it, and the first entries of record 4, two of them before
// the first frame. The expected values come from the numpy decoder of the study of 5 November 2026 (an independent
// implementation): sample count, first and last time from the first frame, sums of the body rates and accelerations
// over the slice, frame times and exposures.

import 'dart:convert';

class Insta360MotionSlice {
  const Insta360MotionSlice({
    required this.model,
    required this.firmware,
    required this.firstFrameTimestamp,
    required this.rollingShutterMs,
    required this.imuBase64,
    required this.framesBase64,
    required this.sampleCount,
    required this.firstTime,
    required this.lastTime,
    required this.rateSums,
    required this.accelerationSums,
    required this.firstRates,
    required this.frameTimes,
    required this.frameExposures,
  });

  final String model;
  final String firmware;
  final int firstFrameTimestamp;
  final double rollingShutterMs;
  final String imuBase64;
  final String framesBase64;
  final int sampleCount;
  final double firstTime;
  final double lastTime;
  final List<double> rateSums;
  final List<double> accelerationSums;
  final List<double> firstRates;
  final List<double> frameTimes;
  final List<double> frameExposures;

  List<int> get imu => base64.decode(imuBase64);

  List<int> get frames => base64.decode(framesBase64);
}

